"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { Icons } from "./icons";
import { applyRelationshipLifecycle, impactAnalysis, proposeKflaLifecycle, requestKflaMetadataReview, requestTaxonomyNodeDefinition, requestTaxonomyNodeLifecycle, saveTaxonomyRelationship, type KflaLifecycleAction, type KflaLifecycleKind, type KflaLifecycleRequest, type TaxonomyNodeLifecycleAction, type TaxonomyNodeLifecycleRequest } from "@/lib/skill-governance";
import { workspaceFindings, type KflaCluster, type KflaCompetency, type KflaFactor, type SkillWorkspace, type TaxonomyNode, type TaxonomyRelationship } from "@/lib/skill-schema";
import { ControlledToolWorkbench } from "./controlled-tool-workbench";

type Mutate = (update: (current: SkillWorkspace) => SkillWorkspace) => void;
type NodeDraft = { kind: "domain" | "group"; id?: string; name: string; description: string; domainId: string };
type StructuralAction = { kind: "domain" | "group"; id: string; action: TaxonomyNodeLifecycleAction };
type KflaHierarchyDraft = { kind: "factor"; value: KflaFactor } | { kind: "cluster"; value: KflaCluster };
const emptyNode = (kind: NodeDraft["kind"], domainId = ""): NodeDraft => ({ kind, name: "", description: "", domainId });

export function TaxonomyStandardWorkbench({ workspace, mutate }: { workspace: SkillWorkspace; mutate: Mutate }) {
  const [view, setView] = useState<"hierarchy" | "graph" | "kfla" | "tools" | "relationships" | "quality">("kfla");
  const [factor, setFactor] = useState("All"); const [query, setQuery] = useState("");
  const [selected, setSelected] = useState<KflaCompetency | null>(null);
  const [editingKfla, setEditingKfla] = useState<KflaCompetency | null>(null);
  const [editingKflaHierarchy, setEditingKflaHierarchy] = useState<KflaHierarchyDraft | null>(null);
  const [kflaEditId, setKflaEditId] = useState(workspace.kfla[0]?.id || "");
  const [nodeDraft, setNodeDraft] = useState<NodeDraft | null>(null);
  const [structuralAction, setStructuralAction] = useState<StructuralAction | null>(null);
  const [relationshipDraft, setRelationshipDraft] = useState<TaxonomyRelationship | null>(null);
  const [relationshipAction, setRelationshipAction] = useState<{ id: string; action: "duplicate" | "archive" | "restore" | "deprecate" } | null>(null);
  const [kflaLifecycle, setKflaLifecycle] = useState<{ kind: KflaLifecycleKind; entityId: string } | null>(null);
  const findings = workspaceFindings(workspace);
  const kfla = useMemo(() => workspace.kfla.filter((item) => (factor === "All" || item.factor === factor) && `${item.name} ${item.publicSummary}`.toLowerCase().includes(query.toLowerCase())), [workspace.kfla, factor, query]);

  function saveNode(actor: string, reason: string) {
    if (!nodeDraft?.name.trim()) return;
    mutate((current) => requestTaxonomyNodeDefinition(current, { kind: nodeDraft.kind, entityId: nodeDraft.id, name: nodeDraft.name, description: nodeDraft.description, domainId: nodeDraft.domainId || undefined, actor, reason }));
    setNodeDraft(null);
  }
  function duplicateNode(kind: "domain" | "group", id: string) {
    setStructuralAction({ kind, id, action: "duplicate" });
  }
  function restoreNode(kind: "domain" | "group", id: string) { setStructuralAction({ kind, id, action: "restore" }); }
  function saveRelationship(actor: string, reason: string) { if (!relationshipDraft) return; mutate((current) => saveTaxonomyRelationship(current, relationshipDraft, actor, reason)); setRelationshipDraft(null); }
  function saveKflaCompetency(actor: string, reason: string) {
    if (!editingKfla) return;
    mutate((current) => requestKflaMetadataReview(current, { kind: "competency", entityId: editingKfla.id, candidate: editingKfla, actor, reason }));
    setEditingKfla(null);
  }
  function saveKflaHierarchy(actor: string, reason: string) {
    if (!editingKflaHierarchy) return;
    const { kind, value } = editingKflaHierarchy;
    mutate((current) => requestKflaMetadataReview(current, { kind, entityId: value.id, candidate: value, actor, reason }));
    setEditingKflaHierarchy(null);
  }

  return <div className="standard-workbench skill-stack">
    <section className="standard-hero panel"><div><span className="section-kicker">GOVERNED STANDARD WORKBENCH</span><h3>Design, test and release a consistent capability language.</h3><p>Working changes stay in n8n. Only approved, validated revisions are released as GitHub-managed JSON.</p></div><div className="standard-state"><b>Revision {workspace.revision}</b><span>{workspace.publication.state === "approved_release" ? "Approved release" : "Working state"}</span><small>{findings.length} validation findings</small></div></section>
    <nav className="standard-tabs" aria-label="Taxonomy workbench views">{[["hierarchy", "Hierarchy CRUD"], ["graph", "Graph & overlap"], ["kfla", "38 KFLA dimensions"], ["tools", "Controlled tools"], ["relationships", "Relationships"], ["quality", "Syntax & quality"]].map(([id, label]) => <button key={id} className={view === id ? "active" : ""} onClick={() => setView(id as typeof view)}>{label}</button>)}</nav>
    {view === "hierarchy" && <Hierarchy workspace={workspace} onCreate={setNodeDraft} onDuplicate={duplicateNode} onRestore={restoreNode} onAction={setStructuralAction}/>}
    {view === "graph" && <TaxonomyGraphExperience workspace={workspace} onRelationship={setRelationshipDraft}/>}
    {view === "kfla" && <><section className="panel kfla-admin-bar"><div><span className="section-kicker">GOVERNED METADATA CRUD</span><b>Edit factors, clusters and competency references</b></div><select aria-label="Select KFLA metadata record" value={kflaEditId} onChange={(event) => setKflaEditId(event.target.value)}>{workspace.kfla.map((item) => <option key={item.id} value={item.id}>{item.number}. {item.name}</option>)}</select><button className="button secondary" onClick={() => setEditingKfla(workspace.kfla.find((item) => item.id === kflaEditId) || null)}><Icons.edit/>Edit competency</button><button className="button secondary" onClick={() => setEditingKflaHierarchy({ kind: "factor", value: workspace.kflaFactors[0] })}><Icons.edit/>Edit factor metadata</button><button className="button secondary" onClick={() => setEditingKflaHierarchy({ kind: "cluster", value: workspace.kflaClusters[0] })}><Icons.edit/>Edit cluster metadata</button><button className="button secondary" onClick={() => setKflaLifecycle({ kind: "competency", entityId: kflaEditId })}><Icons.layers/>Govern lifecycle</button></section><KflaCatalogue workspace={workspace} competencies={kfla} factor={factor} query={query} onFactor={setFactor} onQuery={setQuery} onSelect={setSelected}/></>}
    {view === "tools" && <ControlledToolWorkbench workspace={workspace} mutate={mutate}/>}
    {view === "relationships" && <section className="panel relationship-view"><header><div><span className="section-kicker">CONCEPT GRAPH</span><h3>Governed relationships and replacement chains</h3></div><button className="button primary" onClick={() => setRelationshipDraft({ id: `REL-${Date.now()}`, sourceId: workspace.skills[0]?.id || "", targetId: workspace.skills[1]?.id || "", type: "related", rationale: "", status: "draft" })}><Icons.plus/>Add relationship</button></header>{workspace.relationships.map((relationship) => <article key={relationship.id}><b>{workspace.skills.find((item) => item.id === relationship.sourceId)?.name || relationship.sourceId}</b><span>{relationship.type}</span><b>{workspace.skills.find((item) => item.id === relationship.targetId)?.name || relationship.targetId}</b><p>{relationship.rationale}</p><em>{relationship.status}</em><span className="record-actions"><button aria-label={`Edit relationship ${relationship.id}`} onClick={() => setRelationshipDraft(relationship)}><Icons.edit/></button><button aria-label={`Duplicate relationship ${relationship.id}`} onClick={() => setRelationshipAction({ id: relationship.id, action: "duplicate" })}>⧉</button>{["archived", "retired"].includes(relationship.status) ? <button aria-label={`Restore relationship ${relationship.id}`} onClick={() => setRelationshipAction({ id: relationship.id, action: "restore" })}>↺</button> : <><button aria-label={`Deprecate relationship ${relationship.id}`} onClick={() => setRelationshipAction({ id: relationship.id, action: "deprecate" })}>⊘</button><button aria-label={`Archive relationship ${relationship.id}`} onClick={() => setRelationshipAction({ id: relationship.id, action: "archive" })}><Icons.trash/></button></>}</span></article>)}</section>}
    {view === "quality" && <section className="quality-grid"><article className="panel"><span className="section-kicker">CANONICAL SYNTAX</span><h3>Action + object + outcome</h3><p>Names express a durable capability. Definitions establish meaning and boundaries. Observable evidence proves application.</p><div className="syntax-example"><b>Visualise</b><span>business data</span><em>to enable decision-making</em></div></article><article className="panel"><span className="section-kicker">RELEASE GATE</span><h3>{findings.length ? `${findings.length} findings need attention` : "Ready for accountable approval"}</h3>{findings.length ? <ul>{findings.slice(0, 12).map((finding) => <li key={finding}>{finding}</li>)}</ul> : <p>All configured structural and evidence rules pass.</p>}</article><article className="panel governance-matrix"><span className="section-kicker">AGENT POLICY</span><h3>Suggestive, never authoritative</h3>{["Read approved taxonomy and controlled tools", "Extract evidence from untrusted job text", "Score and explain mapping proposals", "Create drafts in the human review queue", "Never approve, publish, delete or reproduce licensed content"].map((rule, index) => <p key={rule}><b>{String(index + 1).padStart(2, "0")}</b>{rule}</p>)}</article></section>}
    {selected && <KflaDetail selected={selected} workspace={workspace} onSelect={setSelected} onClose={() => setSelected(null)}/>}
    {nodeDraft && <NodeEditor draft={nodeDraft} workspace={workspace} onChange={setNodeDraft} onSave={saveNode} onClose={() => setNodeDraft(null)}/>}
    {relationshipDraft && <RelationshipEditor relationship={relationshipDraft} workspace={workspace} onChange={setRelationshipDraft} onSave={saveRelationship} onClose={() => setRelationshipDraft(null)}/>}
    {relationshipAction && <RelationshipActionEditor
      action={relationshipAction.action}
      onClose={() => setRelationshipAction(null)}
      onApply={(actor, reason) => {
        mutate((current) => applyRelationshipLifecycle(current, relationshipAction.id, relationshipAction.action, actor, reason));
        setRelationshipAction(null);
      }}
    />}
    {editingKfla && <KflaEditor competency={editingKfla} workspace={workspace} onChange={setEditingKfla} onSave={saveKflaCompetency} onClose={() => setEditingKfla(null)}/>}
    {editingKflaHierarchy && <KflaHierarchyEditor draft={editingKflaHierarchy} workspace={workspace} onChange={setEditingKflaHierarchy} onSave={saveKflaHierarchy} onClose={() => setEditingKflaHierarchy(null)}/>}
    {kflaLifecycle && <KflaLifecycleEditor
      workspace={workspace}
      initial={kflaLifecycle}
      onClose={() => setKflaLifecycle(null)}
      onSubmit={(request) => {
        mutate((current) => proposeKflaLifecycle(current, request));
        setKflaLifecycle(null);
      }}
    />}
    {structuralAction && (
      <TaxonomyNodeLifecycleEditor
        workspace={workspace}
        request={structuralAction}
        onClose={() => setStructuralAction(null)}
        onSubmit={(request) => {
          mutate((current) => requestTaxonomyNodeLifecycle(current, request));
          setStructuralAction(null);
        }}
      />
    )}
  </div>;
}

type GraphConcept = { id: string; name: string; kind: "domain" | "group" | "skill"; status: string; parentId?: string; description: string };

function TaxonomyGraphExperience({ workspace, onRelationship }: { workspace: SkillWorkspace; onRelationship: (relationship: TaxonomyRelationship) => void }) {
  const [query, setQuery] = useState("");
  const [kind, setKind] = useState<"all" | GraphConcept["kind"]>("all");
  const [relationshipType, setRelationshipType] = useState<"all" | TaxonomyRelationship["type"]>("all");
  const [selectedId, setSelectedId] = useState(workspace.skills[0]?.id || workspace.groups[0]?.id || workspace.domains[0]?.id || "");
  const concepts = useMemo<GraphConcept[]>(() => [
    ...workspace.domains.map((item) => ({ id: item.id, name: item.name, kind: "domain" as const, status: item.status, description: item.description })),
    ...workspace.groups.map((item) => ({ id: item.id, name: item.name, kind: "group" as const, status: item.status, parentId: item.domainId, description: item.description })),
    ...workspace.skills.map((item) => ({ id: item.id, name: item.name, kind: "skill" as const, status: item.status, parentId: item.groupId, description: item.description })),
  ], [workspace.domains, workspace.groups, workspace.skills]);
  const relationships = useMemo(() => workspace.relationships.filter((item) => !["archived", "retired"].includes(item.status) && (relationshipType === "all" || item.type === relationshipType)), [workspace.relationships, relationshipType]);
  const connectedIds = useMemo(() => new Set(relationships.flatMap((item) => item.sourceId === selectedId ? [item.targetId] : item.targetId === selectedId ? [item.sourceId] : [])), [relationships, selectedId]);
  const visible = useMemo(() => concepts.filter((item) => (kind === "all" || item.kind === kind) && `${item.name} ${item.id} ${item.description}`.toLowerCase().includes(query.toLowerCase())), [concepts, kind, query]);
  const selected = concepts.find((item) => item.id === selectedId) || visible[0];
  const impact = selected ? impactAnalysis(workspace, selected.id) : null;
  const overlap = useMemo(() => {
    const active = workspace.skills.filter((item) => !["archived", "retired"].includes(item.status));
    const tokens = (value: string) => new Set(value.toLowerCase().replace(/[^a-z0-9 ]/g, " ").split(/\s+/).filter((item) => item.length > 3));
    const rows: Array<{ left: typeof active[number]; right: typeof active[number]; score: number; reasons: string[] }> = [];
    for (let left = 0; left < active.length; left += 1) for (let right = left + 1; right < active.length; right += 1) {
      const a = active[left]; const b = active[right]; const at = tokens(`${a.name} ${a.description} ${a.aliases.join(" ")}`); const bt = tokens(`${b.name} ${b.description} ${b.aliases.join(" ")}`);
      const shared = [...at].filter((token) => bt.has(token)); const union = new Set([...at, ...bt]);
      const alias = a.aliases.some((item) => item.toLowerCase() === b.name.toLowerCase() || b.aliases.some((other) => other.toLowerCase() === item.toLowerCase()));
      const score = Math.round(((shared.length / Math.max(1, union.size)) * 80) + (alias ? 20 : 0));
      if (score >= 18) rows.push({ left: a, right: b, score, reasons: [...(alias ? ["alias collision"] : []), ...(shared.length ? [`${shared.length} shared semantic terms`] : [])] });
    }
    return rows.sort((a, b) => b.score - a.score).slice(0, 8);
  }, [workspace.skills]);
  const relationFor = (id: string) => relationships.filter((item) => item.sourceId === id || item.targetId === id);
  const createRelationship = (sourceId: string, targetId: string, type: TaxonomyRelationship["type"] = "related") => onRelationship({ id: `REL-${Date.now()}`, sourceId, targetId, type, rationale: "", status: "draft" });

  return <div className="taxonomy-graph-experience">
    <section className="panel graph-command-bar"><div><span className="section-kicker">GOVERNED TAXONOMY GRAPH</span><h3>Explore structure, overlap and dependency impact</h3><p>Select a concept to trace its hierarchy, semantic relationships, mappings and replacement lineage.</p></div><div className="graph-filters"><input aria-label="Search taxonomy graph" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search concepts, IDs and definitions"/><select aria-label="Filter taxonomy concept type" value={kind} onChange={(event) => setKind(event.target.value as typeof kind)}>{["all", "domain", "group", "skill"].map((item) => <option key={item}>{item}</option>)}</select><select aria-label="Filter taxonomy relationship type" value={relationshipType} onChange={(event) => setRelationshipType(event.target.value as typeof relationshipType)}>{["all", "broader", "narrower", "related", "prerequisite", "replacement", "synonym"].map((item) => <option key={item}>{item}</option>)}</select></div></section>
    <div className="taxonomy-graph-grid"><section className="panel graph-canvas" aria-label="Taxonomy concept graph"><header><b>{visible.length} visible concepts</b><span>{relationships.length} governed edges</span></header><div className="graph-lanes">{(["domain", "group", "skill"] as const).map((lane) => <article key={lane}><h4>{lane === "domain" ? "L1 Domains" : lane === "group" ? "L2 Groups" : "L3 Skills"}</h4>{visible.filter((item) => item.kind === lane).map((item) => <button key={item.id} className={`${selected?.id === item.id ? "selected" : ""} ${connectedIds.has(item.id) ? "connected" : ""}`} onClick={() => setSelectedId(item.id)}><span>{item.name}</span><small>{item.id} · {item.status}</small><em>{relationFor(item.id).length} edges</em></button>)}</article>)}</div></section>
      <aside className="panel graph-inspector">{selected ? <><span className="section-kicker">SELECTED {selected.kind.toUpperCase()}</span><h3>{selected.name}</h3><p>{selected.description}</p><div className="graph-impact"><span><b>{impact?.dependencyCount || 0}</b> total dependencies</span><span><b>{impact?.taxonomyMappings.length || 0}</b> mappings</span><span><b>{impact?.taxonomyProfiles.length || 0}</b> profiles</span><span><b>{impact?.taxonomyRelationships.length || 0}</b> relationships</span></div><h4>Direct connections</h4>{relationFor(selected.id).length ? relationFor(selected.id).map((edge) => { const otherId = edge.sourceId === selected.id ? edge.targetId : edge.sourceId; return <button className="graph-edge" key={edge.id} onClick={() => setSelectedId(otherId)}><span>{edge.type}</span><b>{concepts.find((item) => item.id === otherId)?.name || otherId}</b><small>{edge.status}</small></button>; }) : <p>No explicit semantic relationships yet.</p>}{selected.kind === "skill" && <button className="button primary" disabled={!workspace.skills.some((item) => item.id !== selected.id && !["archived", "retired"].includes(item.status))} onClick={() => createRelationship(selected.id, workspace.skills.find((item) => item.id !== selected.id && !["archived", "retired"].includes(item.status))?.id || "")}><Icons.plus/>Add governed edge</button>}</> : <p>Select a taxonomy concept.</p>}</aside>
    </div>
    <section className="panel overlap-analysis"><header><div><span className="section-kicker">SEMANTIC OVERLAP SIGNALS</span><h3>Candidate duplicates and aliases</h3><p>Signals are deterministic review aids. They never merge or approve concepts automatically.</p></div><span>{overlap.length} candidates</span></header>{overlap.length ? <div className="overlap-table"><div><b>Concept A</b><b>Concept B</b><b>Signal</b><b>Reason</b><b/></div>{overlap.map((item) => <div key={`${item.left.id}-${item.right.id}`}><span><b>{item.left.name}</b><small>{item.left.id}</small></span><span><b>{item.right.name}</b><small>{item.right.id}</small></span><strong>{item.score}%</strong><span>{item.reasons.join(" · ")}</span><button className="button secondary" onClick={() => createRelationship(item.left.id, item.right.id, "synonym")}>Review as synonym</button></div>)}</div> : <p>No material overlap signals under the current deterministic threshold.</p>}</section>
  </div>;
}

function TaxonomyNodeLifecycleEditor({ workspace, request, onClose, onSubmit }: { workspace: SkillWorkspace; request: StructuralAction; onClose: () => void; onSubmit: (request: TaxonomyNodeLifecycleRequest) => void }) {
  const [actor, setActor] = useState(""); const [reason, setReason] = useState(""); const [targetId, setTargetId] = useState(""); const [parentId, setParentId] = useState(""); const [newId, setNewId] = useState("");
  const source = request.kind === "domain" ? workspace.domains.find((item) => item.id === request.id) : workspace.groups.find((item) => item.id === request.id);
  const targets = request.kind === "domain" ? workspace.domains : workspace.groups;
  const impact = source ? impactAnalysis(workspace, source.id) : null;
  const requiresTarget = request.action === "replace" || request.action === "merge";
  return <div className="modal-backdrop"><form className="modal-card" onSubmit={(event) => { event.preventDefault(); onSubmit({ kind: request.kind, action: request.action, entityId: request.id, actor, reason, targetId: targetId || undefined, parentId: parentId || undefined, newId: newId || undefined }); }}><header><div><span className="section-kicker">TAXONOMY STRUCTURAL GOVERNANCE</span><h3>{request.action} {source?.name || request.id}</h3></div><button type="button" aria-label="Close taxonomy lifecycle" onClick={onClose}><Icons.close/></button></header><div className="source-guard"><b>Dependency impact before change</b><span>{impact?.taxonomyGroups.length || 0} groups · {impact?.taxonomySkills.length || 0} skills · {impact?.taxonomyMappings.length || 0} mappings · {impact?.taxonomyProfiles.length || 0} profiles · {impact?.taxonomyTools.length || 0} tools · {impact?.taxonomyRelationships.length || 0} relationships · {impact?.taxonomyJobs.length || 0} jobs</span></div>{requiresTarget && <label><span>Target taxonomy {request.kind}</span><select required value={targetId} onChange={(event) => setTargetId(event.target.value)}><option value="">Select governed target</option>{targets.filter((item) => item.id !== request.id && !["archived", "retired"].includes(item.status)).map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</select></label>}{request.action === "move" && <label><span>Destination domain</span><select required value={parentId} onChange={(event) => setParentId(event.target.value)}><option value="">Select destination domain</option>{workspace.domains.filter((item) => item.id !== (source as typeof workspace.groups[number])?.domainId && !["archived", "retired"].includes(item.status)).map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</select></label>}{request.action === "duplicate" && <label><span>New stable taxonomy ID</span><input required value={newId} onChange={(event) => setNewId(event.target.value)} placeholder={request.kind === "domain" ? "DOM-NEW" : "GRP-NEW"}/></label>}<div className="form-row"><label><span>Accountable proposer</span><input required value={actor} onChange={(event) => setActor(event.target.value)}/></label><label><span>Governance reason</span><textarea required value={reason} onChange={(event) => setReason(event.target.value)}/></label></div>{request.action !== "duplicate" && <p>No structural mutation occurs until an accountable reviewer accepts this request.</p>}<footer><button type="button" className="button secondary" onClick={onClose}>Cancel</button><button className="button primary">{request.action === "duplicate" ? "Create governed draft copy" : "Submit taxonomy change for review"}</button></footer></form></div>;
}

function KflaLifecycleEditor({ workspace, initial, onClose, onSubmit }: { workspace: SkillWorkspace; initial: { kind: KflaLifecycleKind; entityId: string }; onClose: () => void; onSubmit: (request: KflaLifecycleRequest) => void }) {
  const [kind, setKind] = useState(initial.kind); const [entityId, setEntityId] = useState(initial.entityId); const [action, setAction] = useState<KflaLifecycleAction>("move"); const [targetId, setTargetId] = useState(""); const [parentId, setParentId] = useState(""); const [actor, setActor] = useState(""); const [reason, setReason] = useState("");
  const records = kind === "factor" ? workspace.kflaFactors : kind === "cluster" ? workspace.kflaClusters : workspace.kfla;
  const selected = records.find((item) => item.id === entityId) || records[0];
  const impact = selected ? impactAnalysis(workspace, selected.id) : null;
  const changeKind = (next: KflaLifecycleKind) => { const nextRecords = next === "factor" ? workspace.kflaFactors : next === "cluster" ? workspace.kflaClusters : workspace.kfla; setKind(next); setEntityId(nextRecords[0]?.id || ""); setAction(next === "factor" ? "replace" : "move"); setTargetId(""); setParentId(""); };
  const targetRecords = records.filter((item) => item.id !== entityId);
  return <div className="modal-backdrop"><form className="modal" onSubmit={(event) => { event.preventDefault(); onSubmit({ kind, action, entityId, actor, reason, targetId: targetId || undefined, parentId: parentId || undefined }); }}><header><div><span className="section-kicker">KFLA STRUCTURAL GOVERNANCE</span><h2>Submit lifecycle change for review</h2></div><button type="button" aria-label="Close KFLA lifecycle" onClick={onClose}><Icons.close/></button></header><p>No structural mutation occurs now. An accountable reviewer must accept the proposal before children, skill links or replacement lineage change.</p><div className="form-row"><label><span>KFLA record type</span><select value={kind} onChange={(event) => changeKind(event.target.value as KflaLifecycleKind)}>{["factor", "cluster", "competency"].map((item) => <option key={item}>{item}</option>)}</select></label><label><span>KFLA record</span><select required value={entityId} onChange={(event) => { setEntityId(event.target.value); setTargetId(""); }}>{records.map((item) => <option value={item.id} key={item.id}>{item.name} · {item.id}</option>)}</select></label><label><span>KFLA lifecycle action</span><select value={action} onChange={(event) => { setAction(event.target.value as KflaLifecycleAction); setTargetId(""); setParentId(""); }}>{["archive", "restore", "deprecate", "replace", ...(kind === "factor" ? [] : ["move"])].map((item) => <option key={item}>{item}</option>)}</select></label></div><div className="source-guard"><b>Dependency impact</b><span>{impact?.kflaClusters.length || 0} clusters · {impact?.kflaCompetencies.length || 0} competencies · {impact?.kflaSkills.length || 0} skills · {impact?.kflaMappings.length || 0} mappings · {impact?.kflaJobs.length || 0} jobs</span></div>{action === "replace" && <label><span>Replacement KFLA record</span><select required value={targetId} onChange={(event) => setTargetId(event.target.value)}><option value="">Select governed replacement</option>{targetRecords.map((item) => <option value={item.id} key={item.id}>{item.name} · {item.id}</option>)}</select></label>}{action === "move" && kind === "cluster" && <label><span>Destination KFLA factor</span><select required value={parentId} onChange={(event) => setParentId(event.target.value)}><option value="">Select destination factor</option>{workspace.kflaFactors.filter((item) => item.id !== (selected as KflaCluster)?.factorId && !["archived", "retired"].includes(item.status)).map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</select></label>}{action === "move" && kind === "competency" && <label><span>Destination KFLA cluster</span><select required value={parentId} onChange={(event) => setParentId(event.target.value)}><option value="">Select destination cluster</option>{workspace.kflaClusters.filter((item) => item.id !== (selected as KflaCompetency)?.clusterId && !["archived", "retired"].includes(item.status)).map((item) => <option value={item.id} key={item.id}>{workspace.kflaFactors.find((factor) => factor.id === item.factorId)?.name} · {item.name}</option>)}</select></label>}<div className="form-row"><label><span>Accountable proposer</span><input required value={actor} onChange={(event) => setActor(event.target.value)}/></label><label><span>Evidence-based reason</span><textarea required value={reason} onChange={(event) => setReason(event.target.value)}/></label></div><footer><button type="button" className="button secondary" onClick={onClose}>Cancel</button><button className="button primary">Submit KFLA change for review</button></footer></form></div>;
}

function KflaHierarchyEditor({ draft, workspace, onChange, onSave, onClose }: { draft: KflaHierarchyDraft; workspace: SkillWorkspace; onChange: (value: KflaHierarchyDraft) => void; onSave: (actor: string, reason: string) => void; onClose: () => void }) {
  const [actor, setActor] = useState(""); const [reason, setReason] = useState("");
  const value = draft.value;
  const update = (patch: Partial<KflaFactor & KflaCluster>) => onChange({ ...draft, value: { ...value, ...patch } } as KflaHierarchyDraft);
  const choices = draft.kind === "factor" ? workspace.kflaFactors : workspace.kflaClusters;
  return <div className="modal-backdrop"><form className="modal" onSubmit={(event) => { event.preventDefault(); onSave(actor, reason); }}><header><div><span className="section-kicker">KFLA {draft.kind.toUpperCase()} GOVERNANCE</span><h2>Edit public-safe metadata</h2></div><button type="button" onClick={onClose}><Icons.close/></button></header><label><span>Select canonical {draft.kind}</span><select value={value.id} onChange={(event) => { const selected = choices.find((item) => item.id === event.target.value); if (selected) onChange({ kind: draft.kind, value: selected } as KflaHierarchyDraft); }}>{choices.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><div className="source-guard"><b>Canonical identity is protected</b><span>Name and ID remain fixed. The candidate remains non-mutating until accountable approval.</span></div>{draft.kind === "cluster" && <label><span>Factor assignment</span><select value={draft.value.factorId} onChange={(event) => update({ factorId: event.target.value as KflaFactor["id"] })}>{workspace.kflaFactors.filter((item) => item.status !== "archived").map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label>}<label><span>Public-safe description</span><textarea required value={value.description} onChange={(event) => update({ description: event.target.value })}/></label><div className="form-row"><label><span>Source classification</span><select value={value.sourceClassification} onChange={(event) => update({ sourceClassification: event.target.value as KflaFactor["sourceClassification"] })}>{["public", "organization_authored", "licensed"].map((item) => <option key={item}>{item}</option>)}</select></label><label><span>Licence status</span><select value={value.licenceStatus} onChange={(event) => update({ licenceStatus: event.target.value as KflaFactor["licenceStatus"] })}>{["public_metadata", "internal_explanation", "licensed_verified"].map((item) => <option key={item}>{item}</option>)}</select></label><label><span>Lifecycle</span><select value={value.status} onChange={(event) => update({ status: event.target.value as KflaFactor["status"] })}>{["draft", "in_review", "approved", "archived", "deprecated", "retired"].map((item) => <option key={item}>{item}</option>)}</select></label></div><div className="form-row"><label><span>Source version</span><input required value={value.sourceVersion} onChange={(event) => update({ sourceVersion: event.target.value })}/></label><label><span>Review date</span><input required type="date" value={value.reviewDate} onChange={(event) => update({ reviewDate: event.target.value })}/></label><label><span>Content owner</span><input required value={value.contentOwner} onChange={(event) => update({ contentOwner: event.target.value })}/></label></div><div className="form-row"><label><span>Accountable proposer</span><input required value={actor} onChange={(event) => setActor(event.target.value)}/></label><label><span>Evidence-based reason</span><textarea required value={reason} onChange={(event) => setReason(event.target.value)}/></label></div><footer><button type="button" className="button secondary" onClick={onClose}>Cancel</button><button className="button primary">Submit metadata for review</button></footer></form></div>;
}

function Hierarchy({ workspace, onCreate, onDuplicate, onRestore, onAction }: { workspace: SkillWorkspace; onCreate: (draft: NodeDraft) => void; onDuplicate: (kind: "domain" | "group", id: string) => void; onRestore: (kind: "domain" | "group", id: string) => void; onAction: (action: StructuralAction) => void }) {
  return <section className="taxonomy-tree panel"><header><div><span className="section-kicker">L1-L3 TAXONOMY</span><h3>Capability hierarchy</h3></div><div><button className="button secondary" onClick={() => onCreate(emptyNode("group", workspace.domains[0]?.id))}>Add group</button><button className="button primary" onClick={() => onCreate(emptyNode("domain"))}>Add domain</button></div></header>{workspace.domains.map((domain) => <article className="domain-row" key={domain.id}><NodeRow label="L1" node={domain} kind="domain" workspace={workspace} onCreate={onCreate} onDuplicate={onDuplicate} onRestore={onRestore} onAction={onAction}/>{workspace.groups.filter((group) => group.domainId === domain.id).map((group) => <div className="group-row" key={group.id}><NodeRow label="L2" node={group} kind="group" workspace={workspace} onCreate={onCreate} onDuplicate={onDuplicate} onRestore={onRestore} onAction={onAction}/><div>{workspace.skills.filter((skill) => skill.groupId === group.id && !["retired", "archived"].includes(skill.status)).map((skill) => <em key={skill.id}>{skill.name}</em>)}</div></div>)}</article>)}</section>;
}

function NodeRow({ label, node, kind, onCreate, onDuplicate, onRestore, onAction }: { label: string; node: TaxonomyNode & { domainId?: string }; kind: "domain" | "group"; workspace: SkillWorkspace; onCreate: (draft: NodeDraft) => void; onDuplicate: (kind: "domain" | "group", id: string) => void; onRestore: (kind: "domain" | "group", id: string) => void; onAction: (action: StructuralAction) => void }) {
  const inactive = ["archived", "retired"].includes(node.status); return <><b>{label}</b><span><strong>{node.name}</strong><small>{node.description || "Description required"} · {node.status}</small></span><span className="record-actions"><button aria-label={`Edit ${node.name}`} onClick={() => onCreate({ kind, id: node.id, name: node.name, description: node.description, domainId: node.domainId || "" })}><Icons.edit/></button><button aria-label={`Duplicate ${node.name}`} onClick={() => onDuplicate(kind, node.id)}>⧉</button>{inactive ? <button aria-label={`Restore ${node.name}`} onClick={() => onRestore(kind, node.id)}>↺</button> : <>{kind === "group" && <button aria-label={`Move ${node.name}`} onClick={() => onAction({ kind, id: node.id, action: "move" })}>↔</button>}<button aria-label={`Deprecate ${node.name}`} onClick={() => onAction({ kind, id: node.id, action: "deprecate" })}>⊘</button><button aria-label={`Replace ${node.name}`} onClick={() => onAction({ kind, id: node.id, action: "replace" })}>⇢</button><button aria-label={`Merge ${node.name}`} onClick={() => onAction({ kind, id: node.id, action: "merge" })}><Icons.layers/></button><button aria-label={`Archive ${node.name}`} onClick={() => onAction({ kind, id: node.id, action: "archive" })}><Icons.trash/></button></>}</span></>;
}

function KflaCatalogue({ workspace, competencies, factor, query, onFactor, onQuery, onSelect }: { workspace: SkillWorkspace; competencies: KflaCompetency[]; factor: string; query: string; onFactor: (value: string) => void; onQuery: (value: string) => void; onSelect: (item: KflaCompetency) => void }) {
  return <section className="kfla-panel panel"><header><div><span className="section-kicker">GOVERNED KFLA REFERENCE LAYER · 4 FACTORS · 12 CLUSTERS</span><h3>38 KFLA competency names</h3><p>Cluster labels and summaries are organization-authored navigation content pending licensed verification. Official definitions remain backend-only and access-controlled.</p></div><div className="kfla-filters"><input aria-label="Search KFLA dimensions" value={query} onChange={(event) => onQuery(event.target.value)} placeholder="Search dimensions"/><select aria-label="Filter KFLA factor" value={factor} onChange={(event) => onFactor(event.target.value)}>{["All", ...workspace.kflaFactors.map((item) => item.name)].map((item) => <option key={item}>{item}</option>)}</select></div></header><div className="kfla-factor-strip">{workspace.kflaFactors.map((item) => <button key={item.id} className={factor === item.name ? "active" : ""} onClick={() => onFactor(factor === item.name ? "All" : item.name)}><b>{item.name}</b><span>{workspace.kflaClusters.filter((cluster) => cluster.factorId === item.id).length} clusters</span><small>{workspace.kfla.filter((competency) => competency.factorId === item.id).length} competencies</small></button>)}</div><div className="kfla-cluster-strip">{workspace.kflaClusters.filter((cluster) => factor === "All" || workspace.kflaFactors.find((item) => item.id === cluster.factorId)?.name === factor).map((cluster) => <article key={cluster.id}><b>{cluster.name}</b><span>{workspace.kfla.filter((item) => item.clusterId === cluster.id).length} competencies</span><small>{cluster.description}</small><em>{cluster.assignmentBasis.replaceAll("_", " ")}</em></article>)}</div><div className="kfla-grid">{competencies.map((item) => <button className="kfla-card" key={item.id} data-preview={item.publicSummary} aria-label={`Open ${item.name} competency deep dive`} onClick={() => onSelect(item)}><b>{String(item.number).padStart(2, "0")}</b><span><strong>{item.name}</strong><small>{item.factor} · {workspace.kflaClusters.find((cluster) => cluster.id === item.clusterId)?.name}</small><em>{item.publicSummary}</em></span></button>)}</div></section>;
}

function KflaDetail({ selected, workspace, onSelect, onClose }: { selected: KflaCompetency; workspace: SkillWorkspace; onSelect: (item: KflaCompetency) => void; onClose: () => void }) {
  const dialog = useRef<HTMLElement>(null);
  useEffect(() => {
    const previous = document.activeElement as HTMLElement | null; const priorOverflow = document.body.style.overflow; document.body.style.overflow = "hidden";
    dialog.current?.focus();
    const keydown = (event: KeyboardEvent) => {
      if (event.key === "Escape") { event.preventDefault(); onClose(); return; }
      if (event.key !== "Tab" || !dialog.current) return;
      const focusable = Array.from(dialog.current.querySelectorAll<HTMLElement>('button,a[href],input,select,textarea,[tabindex]:not([tabindex="-1"])')).filter((item) => !item.hasAttribute("disabled"));
      if (!focusable.length) return; const first = focusable[0]; const last = focusable[focusable.length - 1];
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
    };
    document.addEventListener("keydown", keydown);
    return () => { document.removeEventListener("keydown", keydown); document.body.style.overflow = priorOverflow; previous?.focus(); };
  }, [onClose]);
  function backdropClose(event: React.MouseEvent<HTMLDivElement>) { if (event.target !== event.currentTarget || window.getSelection()?.toString()) return; onClose(); }
  const titleId = `kfla-title-${selected.id}`;
  return <div className="modal-backdrop kfla-backdrop" onMouseDown={backdropClose}><article ref={dialog} role="dialog" aria-modal="true" aria-labelledby={titleId} tabIndex={-1} className="modal-card kfla-detail"><header><div><span className="section-kicker">KFLA {String(selected.number).padStart(2, "0")} · {selected.factor} · {workspace.kflaClusters.find((cluster) => cluster.id === selected.clusterId)?.name}</span><h3 id={titleId}>{selected.name}</h3></div><button aria-label="Close KFLA detail" onClick={onClose}><Icons.close/></button></header><div className="kfla-detail-body"><div className="source-guard"><b>{selected.sourceClassification.replaceAll("_", " ")} · {selected.licenceStatus.replaceAll("_", " ")}</b><span>{selected.boundaryNotes}</span></div><div className="kfla-detail-meta"><span><b>Owner</b>{selected.contentOwner}</span><span><b>Source version</b>{selected.sourceVersion}</span><span><b>Reviewed</b>{selected.reviewDate}</span><span><b>Status</b>{selected.reviewStatus.replaceAll("_", " ")}</span></div><h4>Internal interpretation</h4><p>{selected.internalInterpretation}</p>{selected.licensedDefinitionRef && <div className="licensed-guard"><b>Licensed definition available</b><span>Content is retrieved only through the protected role-authorized backend and is absent from this public bundle.</span></div>}<div className="kfla-detail-grid"><DetailList title="Inclusion criteria" items={selected.inclusionCriteria}/><DetailList title="Exclusion criteria" items={selected.exclusionCriteria}/><DetailList title="Positive examples" items={selected.positiveExamples}/><DetailList title="Counterexamples" items={selected.counterExamples}/><DetailList title="Typical evidence" items={selected.typicalEvidence}/><DetailList title="Common mapping mistakes" items={selected.mappingMistakes}/></div><h4>Related competencies</h4><div className="related-chips">{selected.relatedCompetencyIds.map((id) => <button key={id} onClick={() => onSelect(workspace.kfla.find((item) => item.id === id) || selected)}>{workspace.kfla.find((item) => item.id === id)?.name}</button>)}</div><h4>Relevant skills and jobs</h4><p>{workspace.skills.filter((skill) => skill.kflaCompetencyId === selected.id).map((skill) => skill.name).join(" · ") || "No approved skill mappings yet."}</p><p>{workspace.jobDescriptions.filter((job) => workspace.mappings.some((mapping) => mapping.jobDescriptionId === job.id && workspace.skills.find((skill) => skill.id === mapping.skillId)?.kflaCompetencyId === selected.id)).map((job) => job.title).join(" · ") || "No governed job mappings yet."}</p><h4>Provenance</h4>{selected.provenance.map((source) => <a key={source.url} href={source.url} target="_blank" rel="noreferrer">{source.label} · {source.access} · reviewed {source.reviewedAt}</a>)}</div></article></div>;
}
function DetailList({ title, items }: { title: string; items: string[] }) { return <section><h4>{title}</h4><ul>{items.map((item) => <li key={item}>{item}</li>)}</ul></section>; }

function KflaEditor({ competency, workspace, onChange, onSave, onClose }: { competency: KflaCompetency; workspace: SkillWorkspace; onChange: (value: KflaCompetency) => void; onSave: (actor: string, reason: string) => void; onClose: () => void }) {
  const [actor, setActor] = useState(""); const [reason, setReason] = useState("");
  const list = (key: "observableSignals" | "inclusionCriteria" | "exclusionCriteria" | "positiveExamples" | "counterExamples" | "typicalEvidence" | "mappingMistakes", value: string) => onChange({ ...competency, [key]: value.split("\n").map((item) => item.trim()).filter(Boolean) });
  return <div className="modal-backdrop"><form className="modal kfla-editor" onSubmit={(event) => { event.preventDefault(); onSave(actor, reason); }}><header><div><span className="section-kicker">GOVERNED KFLA METADATA</span><h2>{competency.number}. {competency.name}</h2></div><button type="button" onClick={onClose}><Icons.close/></button></header><div className="source-guard"><b>Public-safe metadata only</b><span>Licensed definitions and protected references are administered through the role-authorized backend and cannot be edited here. This candidate remains non-mutating until approval.</span></div><div className="form-row"><label><span>Cluster / move</span><select value={competency.clusterId} onChange={(event) => onChange({ ...competency, clusterId: event.target.value })}>{workspace.kflaClusters.filter((item) => item.status !== "archived").map((item) => <option value={item.id} key={item.id}>{workspace.kflaFactors.find((factor) => factor.id === item.factorId)?.name} · {item.name}</option>)}</select></label><label><span>Reference state</span><select value={competency.enabled ? "enabled" : "archived"} onChange={(event) => onChange({ ...competency, enabled: event.target.value === "enabled" })}><option value="enabled">Enabled</option><option value="archived">Archived / hidden</option></select></label><label><span>Review status</span><select value={competency.reviewStatus} onChange={(event) => onChange({ ...competency, reviewStatus: event.target.value as KflaCompetency["reviewStatus"] })}>{["verified_public_metadata", "internal_review", "licensed_review_required"].map((item) => <option key={item}>{item}</option>)}</select></label></div><div className="form-row"><label><span>Content owner</span><input required value={competency.contentOwner} onChange={(event) => onChange({ ...competency, contentOwner: event.target.value })}/></label><label><span>Source version</span><input required value={competency.sourceVersion} onChange={(event) => onChange({ ...competency, sourceVersion: event.target.value })}/></label><label><span>Review date</span><input required type="date" value={competency.reviewDate} onChange={(event) => onChange({ ...competency, reviewDate: event.target.value })}/></label></div><label><span>Public-safe summary</span><textarea required value={competency.publicSummary} onChange={(event) => onChange({ ...competency, publicSummary: event.target.value })}/></label><label><span>Internal interpretation</span><textarea required value={competency.internalInterpretation} onChange={(event) => onChange({ ...competency, internalInterpretation: event.target.value })}/></label><label><span>Boundary and licence note</span><textarea required value={competency.boundaryNotes} onChange={(event) => onChange({ ...competency, boundaryNotes: event.target.value })}/></label><div className="kfla-list-editor">{(["observableSignals", "inclusionCriteria", "exclusionCriteria", "positiveExamples", "counterExamples", "typicalEvidence", "mappingMistakes"] as const).map((key) => <label key={key}><span>{key.replace(/([A-Z])/g, " $1")}</span><textarea value={competency[key].join("\n")} onChange={(event) => list(key, event.target.value)} placeholder="One governed entry per line"/></label>)}</div><fieldset className="skill-checkboxes"><legend>Related competencies</legend>{workspace.kfla.filter((item) => item.id !== competency.id).map((item) => <label key={item.id}><input type="checkbox" checked={competency.relatedCompetencyIds.includes(item.id)} onChange={(event) => onChange({ ...competency, relatedCompetencyIds: event.target.checked ? [...competency.relatedCompetencyIds, item.id] : competency.relatedCompetencyIds.filter((id) => id !== item.id) })}/>{item.number}. {item.name}</label>)}</fieldset><div className="form-row"><label><span>Accountable proposer</span><input required value={actor} onChange={(event) => setActor(event.target.value)}/></label><label><span>Evidence-based reason</span><textarea required value={reason} onChange={(event) => setReason(event.target.value)}/></label></div><footer><button type="button" className="button secondary" onClick={onClose}>Cancel</button><button className="button primary">Submit metadata for review</button></footer></form></div>;
}

function NodeEditor({ draft, workspace, onChange, onSave, onClose }: { draft: NodeDraft; workspace: SkillWorkspace; onChange: (draft: NodeDraft) => void; onSave: (actor: string, reason: string) => void; onClose: () => void }) { const [actor, setActor] = useState(""); const [reason, setReason] = useState(""); return <div className="modal-backdrop"><form className="modal-card skill-modal" onSubmit={(event) => { event.preventDefault(); onSave(actor, reason); }}><header><h3>{draft.id ? "Edit" : "Create"} {draft.kind}</h3><button type="button" onClick={onClose}><Icons.close/></button></header><p>The candidate remains in the review payload. The active hierarchy changes only after accountable approval.</p>{draft.kind === "group" && <label><span>Parent domain</span><select value={draft.domainId} onChange={(event) => onChange({ ...draft, domainId: event.target.value })}>{workspace.domains.filter((item) => !["retired", "archived"].includes(item.status)).map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</select></label>}<label><span>Canonical name</span><input required value={draft.name} onChange={(event) => onChange({ ...draft, name: event.target.value })}/></label><label><span>Definition and boundary</span><textarea required value={draft.description} onChange={(event) => onChange({ ...draft, description: event.target.value })}/></label><div className="form-row"><label><span>Accountable proposer</span><input required value={actor} onChange={(event) => setActor(event.target.value)}/></label><label><span>Governance reason</span><textarea required value={reason} onChange={(event) => setReason(event.target.value)}/></label></div><footer><button type="button" className="button secondary" onClick={onClose}>Cancel</button><button className="button primary">Submit definition for review</button></footer></form></div>; }
function RelationshipEditor({ relationship, workspace, onChange, onSave, onClose }: { relationship: TaxonomyRelationship; workspace: SkillWorkspace; onChange: (draft: TaxonomyRelationship) => void; onSave: (actor: string, reason: string) => void; onClose: () => void }) {
  const [actor, setActor] = useState(""); const [reason, setReason] = useState("");
  return <div className="modal-backdrop"><form className="modal-card" onSubmit={(event) => { event.preventDefault(); onSave(actor, reason); }}><header><h3>Govern relationship</h3><button type="button" onClick={onClose}><Icons.close/></button></header><label><span>Source concept</span><select value={relationship.sourceId} onChange={(event) => onChange({ ...relationship, sourceId: event.target.value })}>{workspace.skills.filter((item) => !["archived", "retired"].includes(item.status)).map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</select></label><label><span>Relationship</span><select value={relationship.type} onChange={(event) => onChange({ ...relationship, type: event.target.value as TaxonomyRelationship["type"] })}>{["broader", "narrower", "related", "prerequisite", "replacement", "synonym"].map((item) => <option key={item}>{item}</option>)}</select></label><label><span>Target concept</span><select value={relationship.targetId} onChange={(event) => onChange({ ...relationship, targetId: event.target.value })}>{workspace.skills.filter((item) => !["archived", "retired"].includes(item.status)).map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</select></label><label><span>Rationale</span><textarea required value={relationship.rationale} onChange={(event) => onChange({ ...relationship, rationale: event.target.value })}/></label><div className="form-row"><label><span>Accountable actor</span><input required value={actor} onChange={(event) => setActor(event.target.value)}/></label><label><span>Change reason</span><input required value={reason} onChange={(event) => setReason(event.target.value)}/></label></div><footer><button type="button" className="button secondary" onClick={onClose}>Cancel</button><button className="button primary">Save relationship</button></footer></form></div>;
}

function RelationshipActionEditor({ action, onClose, onApply }: { action: "duplicate" | "archive" | "restore" | "deprecate"; onClose: () => void; onApply: (actor: string, reason: string) => void }) {
  const [actor, setActor] = useState(""); const [reason, setReason] = useState("");
  return <div className="modal-backdrop"><form className="modal-card" onSubmit={(event) => { event.preventDefault(); onApply(actor, reason); }}><header><div><span className="section-kicker">RELATIONSHIP LIFECYCLE</span><h3>{action} governed relationship</h3></div><button type="button" onClick={onClose}><Icons.close/></button></header><p>The relationship remains recoverable in immutable object history. Approved releases require a separate human release decision.</p><label><span>Accountable actor</span><input required value={actor} onChange={(event) => setActor(event.target.value)}/></label><label><span>Evidence-based reason</span><textarea required value={reason} onChange={(event) => setReason(event.target.value)}/></label><footer><button type="button" className="button secondary" onClick={onClose}>Cancel</button><button className="button primary">Apply governed action</button></footer></form></div>;
}
